#include "block_protocol.h"
#include <algorithm>
#include <charconv>
#include <stdexcept>
#include <set>
#include <cctype>
namespace {
constexpr int SOH=1,STX=2,EOT=4,ACK=6,NAK=21,CAN=24,CRC='C';
void options(const BlockOptions& o){if(static_cast<unsigned>(o.mode)>3||o.timeout_ms<100||o.timeout_ms>60000||o.retries<1||o.retries>10)throw std::runtime_error("Invalid transfer mode/timeout/retry limit.");}
void put(BlockLink& io,int byte){const char c=static_cast<char>(byte);io.check();io.write(std::string_view(&c,1));}
int get(BlockLink& io,unsigned timeout){io.check();const auto c=io.byte(timeout);io.check();if(c==CAN){const auto next=io.byte(timeout);if(next==CAN)throw std::runtime_error("Remote cancelled the transfer.");return next;}return c;}
bool handshake(const BlockOptions& o,BlockLink& io){for(unsigned n=0;n<o.retries;++n){const auto c=get(io,o.timeout_ms);if(c==CRC&&o.mode!=BlockMode::XChecksum)return true;if(c==NAK)return false;}throw std::runtime_error("Handshake timed out; check peer protocol/mode.");}
void acknowledged(std::string_view bytes,const BlockOptions& o,BlockLink& io){for(unsigned n=0;n<o.retries;++n){io.check();io.write(bytes);const auto c=get(io,o.timeout_ms);if(c==ACK)return;if(io.progress)io.progress(0,n+1);}throw std::runtime_error("ACK retry limit exceeded.");}
struct Packet {int control=-1;unsigned number=0;std::string data,encoded;bool valid=false;};
Packet packet(const BlockOptions& o,BlockLink& io,bool crc){Packet p;p.control=get(io,o.timeout_ms);if(p.control!=SOH&&p.control!=STX)return p;const size_t count=p.control==SOH?128:1024;std::string raw;raw.reserve(count+4);
    for(size_t i=0;i<count+2+(crc?2:1);++i){const int c=io.byte(o.timeout_ms);io.check();if(c<0){p.control=-1;return p;}raw.push_back(static_cast<char>(c));}
    p.number=static_cast<unsigned char>(raw[0]);p.data=raw.substr(2,count);p.encoded=std::move(raw);if((p.number^static_cast<unsigned char>(p.encoded[1]))!=255)return p;
    if(crc){const auto expected=xmodem_crc(p.data);p.valid=static_cast<unsigned char>(p.encoded[count+2])==(expected>>8)&&static_cast<unsigned char>(p.encoded[count+3])==(expected&255);}else {unsigned sum=0;for(const unsigned char c:p.data)sum+=c;p.valid=static_cast<unsigned char>(p.encoded[count+2])==(sum&255);}return p;
}
void purge(BlockLink& io){for(size_t n=0;n<65536;++n){io.check();if(io.byte(50)<0)return;}throw std::runtime_error("Continuous unexpected input; transfer aborted.");}
void linger(const BlockOptions& o,BlockLink& io,bool crc){for(unsigned n=0;n<2;++n){const auto p=packet(o,io,crc);if(p.control<0)return;if(p.control==EOT||(p.valid&&p.number==0&&!p.data.empty()&&p.data[0]==0))put(io,ACK);}}
}
uint16_t xmodem_crc(std::string_view bytes){uint16_t crc=0;for(const unsigned char c:bytes){crc^=static_cast<uint16_t>(c)<<8;for(unsigned i=0;i<8;++i)crc=static_cast<uint16_t>((crc&0x8000)?(crc<<1)^0x1021:crc<<1);}return crc;}
bool safe_transfer_name(std::string_view name){if(name.empty()||name.size()>100||name=="."||name==".."||name.back()=='.'||name.back()==' ')return false;std::string base;for(const unsigned char c:name){if(c<32||c>=127||std::string_view("<>:\"/\\|?*").find(static_cast<char>(c))!=std::string_view::npos)return false;base+=static_cast<char>(std::toupper(c));}base.resize(base.find('.')==std::string::npos?base.size():base.find('.'));if(base=="CON"||base=="PRN"||base=="AUX"||base=="NUL"||((base.rfind("COM",0)==0||base.rfind("LPT",0)==0)&&base.size()==4&&base[3]>='1'&&base[3]<='9'))return false;return true;}
std::string xmodem_packet(unsigned number,std::string_view data,size_t size,bool crc){if((size!=128&&size!=1024)||data.size()>size)throw std::runtime_error("Invalid block length.");std::string out;out.reserve(size+5);out+=size==128?SOH:STX;out.push_back(static_cast<char>(number));out.push_back(static_cast<char>(255-(number&255)));out.append(data);out.append(size-data.size(),char(26));if(crc){const auto sum=xmodem_crc(std::string_view(out).substr(3));out.push_back(static_cast<char>(sum>>8));out.push_back(static_cast<char>(sum));}else{unsigned sum=0;for(size_t i=3;i<out.size();++i)sum+=static_cast<unsigned char>(out[i]);out.push_back(static_cast<char>(sum));}return out;}
void block_send(const BlockOptions& o,const std::vector<BlockSource>& sources,BlockLink& io){options(o);const bool batch=o.mode==BlockMode::Ymodem;if(sources.empty()||sources.size()>128||(!batch&&sources.size()!=1))throw std::runtime_error("Choose 1 file for XMODEM or 1..128 for YMODEM.");std::set<std::string> names;uint64_t total=0;for(const auto& s:sources){if(!s.read||s.size>64ULL*1024*1024*1024||(batch&&(!safe_transfer_name(s.name)||!names.insert(s.name).second)))throw std::runtime_error("Invalid/duplicate transfer filename or size.");if(total>64ULL*1024*1024*1024-s.size)throw std::runtime_error("Transfer exceeds 64 GiB.");total+=s.size;}
    uint64_t done=0;for(const auto& source:sources){bool crc=handshake(o,io);if(batch){std::string header(128,0);const auto fields=source.name+'\0'+std::to_string(source.size)+'\0';if(fields.size()>header.size())throw std::runtime_error("YMODEM metadata exceeds block 0.");header.replace(0,fields.size(),fields);acknowledged(xmodem_packet(0,header,128,crc),o,io);crc=handshake(o,io);}
        unsigned sequence=1;const size_t block=o.mode==BlockMode::XChecksum||o.mode==BlockMode::XCrc?128:1024;
        for(uint64_t offset=0;offset<source.size;){const auto count=static_cast<size_t>(std::min<uint64_t>(block,source.size-offset));io.check();const auto data=source.read(offset,count);if(data.size()!=count)throw std::runtime_error("Source file changed or read failed.");const auto bytes=xmodem_packet(sequence,data,block,crc);acknowledged(bytes,o,io);offset+=count;done+=count;++sequence;if(io.progress)io.progress(done,0);}
        acknowledged(std::string(1,char(EOT)),o,io);
    }if(batch){const bool crc=handshake(o,io);acknowledged(xmodem_packet(0,std::string(128,0),128,crc),o,io);}
}
void block_receive(const BlockOptions& o,BlockSink& sink,BlockLink& io,std::optional<uint64_t> expected_size){options(o);const bool batch=o.mode==BlockMode::Ymodem,crc=o.mode!=BlockMode::XChecksum;if(expected_size&&*expected_size>64ULL*1024*1024*1024)throw std::runtime_error("Receive size exceeds 64 GiB.");unsigned files=0,retries=0,expected=1;uint64_t written=0,total=0;bool header=batch,open=false;std::string last;auto size=expected_size;const int first=crc?CRC:NAK;
    if(!batch){sink.begin("",size);open=true;}put(io,first);
    while(true){const auto p=packet(o,io,crc);io.check();if(p.control==EOT){if(header){put(io,ACK);put(io,first);continue;}if(size&&written!=*size)throw std::runtime_error("EOT before declared file size; output not committed.");if(!open)throw std::runtime_error("Unexpected EOT.");sink.commit();open=false;put(io,ACK);if(!batch){linger(o,io,crc);return;}header=true;expected=0;last.clear();retries=0;put(io,first);continue;}
        if(!p.valid){if(++retries>o.retries)throw std::runtime_error("Receive retry limit exceeded.");if(p.control>=0)purge(io);put(io,header||(!written&&expected==1)?first:NAK);if(io.progress)io.progress(total,retries);continue;}
        if(header){if(p.number!=0)throw std::runtime_error("Expected YMODEM pathname block 0.");if(p.data[0]==0){put(io,ACK);linger(o,io,crc);return;}if(++files>128)throw std::runtime_error("YMODEM batch exceeds 128 files.");const auto end=p.data.find('\0');if(end==std::string::npos||!safe_transfer_name(std::string_view(p.data).substr(0,end)))throw std::runtime_error("Unsafe YMODEM filename.");size.reset();const auto start=end+1,finish=p.data.find_first_of(std::string(" \0",2),start);if(start<p.data.size()&&p.data[start]){uint64_t length=0;const auto at=finish==std::string::npos?p.data.size():finish;const auto r=std::from_chars(p.data.data()+start,p.data.data()+at,length);if(r.ec!=std::errc{}||r.ptr!=p.data.data()+at||length>64ULL*1024*1024*1024)throw std::runtime_error("Invalid YMODEM file size.");size=length;}sink.begin(p.data.substr(0,end),size);open=true;written=0;expected=1;header=false;last=p.encoded;retries=0;put(io,ACK);put(io,first);continue;}
        if(p.number==((expected-1)&255)){if(p.encoded!=last)throw std::runtime_error("Duplicate block changed its bytes.");put(io,ACK);if(expected==1&&!written&&batch)put(io,first);continue;}
        if(p.number!=(expected&255))throw std::runtime_error("Unexpected block sequence; transfer aborted.");if(size&&written>=*size)throw std::runtime_error("Data exceeds declared file size.");const size_t n=size?static_cast<size_t>(std::min<uint64_t>(p.data.size(),*size-written)):p.data.size();if(total>64ULL*1024*1024*1024-n)throw std::runtime_error("Receive exceeds 64 GiB.");sink.append(std::string_view(p.data).substr(0,n));written+=n;total+=n;last=p.encoded;++expected;retries=0;put(io,ACK);if(io.progress)io.progress(total,0);
    }
}
